import java.util.ArrayList;

public class MinHeap {
    ArrayList<Integer> heap = new ArrayList<>();

    void heapifyUp(int i) {
        while (i > 0 && heap.get((i-1)/2) > heap.get(i)) {
            int temp = heap.get(i);
            heap.set(i, heap.get((i-1)/2));
            heap.set((i-1)/2, temp);
            i = (i-1)/2;
        }
    }

    void heapifyDown(int i) {
        int n = heap.size(), smallest = i;
        int l = 2*i+1, r = 2*i+2;
        if (l < n && heap.get(l) < heap.get(smallest)) smallest = l;
        if (r < n && heap.get(r) < heap.get(smallest)) smallest = r;
        if (smallest != i) {
            int temp = heap.get(i);
            heap.set(i, heap.get(smallest));
            heap.set(smallest, temp);
            heapifyDown(smallest);
        }
    }

    void insert(int val) {
        heap.add(val);
        heapifyUp(heap.size() - 1);
    }

    int extractMin() {
        int min = heap.get(0);
        heap.set(0, heap.get(heap.size()-1));
        heap.remove(heap.size()-1);
        if (!heap.isEmpty()) heapifyDown(0);
        return min;
    }

    public static void main(String[] args) {
        MinHeap h = new MinHeap();
        h.insert(15); h.insert(10); h.insert(20); h.insert(5);
        System.out.println("Min: " + h.heap.get(0));       // 5
        System.out.println("Extracted: " + h.extractMin()); // 5
    }
}

