#include <stdio.h>

typedef struct { int priority; int data; } Task;

Task pq[100];
int pqSize = 0;

void swap(Task *a, Task *b) { Task t = *a; *a = *b; *b = t; }

void pqPush(int priority, int data) {
    pq[pqSize].priority = priority;
    pq[pqSize].data = data;
    int i = pqSize++;
    while (i > 0 && pq[(i-1)/2].priority > pq[i].priority) {
        swap(&pq[i], &pq[(i-1)/2]);
        i = (i-1)/2;
    }
}

Task pqPop() {
    Task top = pq[0];
    pq[0] = pq[--pqSize];
    int i = 0;
    while (1) {
        int smallest = i, l = 2*i+1, r = 2*i+2;
        if (l < pqSize && pq[l].priority < pq[smallest].priority) smallest = l;
        if (r < pqSize && pq[r].priority < pq[smallest].priority) smallest = r;
        if (smallest == i) break;
        swap(&pq[i], &pq[smallest]);
        i = smallest;
    }
    return top;
}

int main() {
    pqPush(3, 100); pqPush(1, 200); pqPush(2, 300);
    while (pqSize > 0) {
        Task t = pqPop();
        printf("Priority %d: Data %d\n", t.priority, t.data);
    }
    // Priority 1: Data 200
    // Priority 2: Data 300
    // Priority 3: Data 100
    return 0;
}
